33	func postArtifact(t *testing.T, router *gin.Engine, body string) *httptest.ResponseRecorder {
34		t.Helper()
35		recorder := httptest.NewRecorder()
36		request := httptest.NewRequest(http.MethodPost, "/v1/artifacts", strings.NewReader(body))
37		router.ServeHTTP(recorder, request)
38		return recorder
39	}
