41	func getArtifacts(t *testing.T, router *gin.Engine, query string) *httptest.ResponseRecorder {
42		t.Helper()
43		recorder := httptest.NewRecorder()
44		request := httptest.NewRequest(http.MethodGet, "/v1/artifacts?"+query, nil)
45		router.ServeHTTP(recorder, request)
46		return recorder
