49	func decodeBody(t *testing.T, recorder *httptest.ResponseRecorder) map[string]any {
50		t.Helper()
51		var body map[string]any
52		if err := json.Unmarshal(recorder.Body.Bytes(), &body); err != nil {
53			t.Fatalf("decode response: %v", err)
54		}
55		return body
56	}
57	
58	func errorCode(t *testing.T, recorder *httptest.ResponseRecorder) string {
59		t.Helper()
60		body := decodeBody(t, recorder)
61		errObj, ok := body["error"].(map[string]any)
62		if !ok {
63			t.Fatalf("response has no error object: %v", body)
64		}
65		code, _ := errObj["code"].(string)
66		if _, ok := errObj["message"].(string); !ok {
67			t.Fatalf("error object has no message string: %v", errObj)
68		}
69		return code
70	}
