77	func TestRegisterArtifactCreated(t *testing.T) {
78		router, _ := newTestRouter(t)
79	
80		recorder := postArtifact(t, router, validRegistration(testDigestA))
81		if recorder.Code != http.StatusCreated {
82			t.Fatalf("status = %d, want %d (%s)", recorder.Code, http.StatusCreated, recorder.Body)
83		}
84		body := decodeBody(t, recorder)
85		want := map[string]any{
86			"repository":         "team/app",
87			"digest":             testDigestA,
88			"tag":                "latest",
89			"signature_verified": true,
90			"retention_days":     float64(30),
91			"size_bytes":         float64(1024),
92		}
93		for key, value := range want {
94			if body[key] != value {
95				t.Fatalf("field %s = %v, want %v", key, body[key], value)
96			}
97		}
98		pushedAt, ok := body["pushed_at"].(string)
99		if !ok {
100			t.Fatalf("pushed_at missing or not a string: %v", body)
101		}
102		parsed, err := time.Parse(time.RFC3339, pushedAt)
103		if err != nil {
104			t.Fatalf("pushed_at %q is not RFC3339: %v", pushedAt, err)
105		}
106		if parsed.Location() != time.UTC {
107			t.Fatalf("pushed_at %q is not UTC", pushedAt)
108		}
109	}
