111	func TestRegisterArtifactNormalizesAndIgnoresUnknownFields(t *testing.T) {
112		router, _ := newTestRouter(t)
113	
114		recorder := postArtifact(t, router, `{"repository":"  team/app  ","digest":"`+testDigestA+`",`+
115			`"tag":"  latest ","signature_verified":false,"retention_days":1,"size_bytes":0,"extra":"ignored"}`)
116		if recorder.Code != http.StatusCreated {
117			t.Fatalf("status = %d, want %d (%s)", recorder.Code, http.StatusCreated, recorder.Body)
118		}
119		body := decodeBody(t, recorder)
120		if body["repository"] != "team/app" || body["tag"] != "latest" {
121			t.Fatalf("values were not trimmed: %v", body)
122		}
123	}
