125	func TestRegisterArtifactRejectsInvalidInput(t *testing.T) {
126		cases := map[string]string{
127			"empty body":            ``,
128			"json array":            `[{"repository":"team/app"}]`,
129			"json scalar":           `"text"`,
130			"json null":             `null`,
131			"trailing object":       validRegistration(testDigestA) + ` {}`,
132			"malformed json":        `{"repository":`,
133			"missing repository":    `{"digest":"` + testDigestA + `","tag":"latest","signature_verified":true,"retention_days":30,"size_bytes":1}`,
134			"missing digest":        `{"repository":"team/app","tag":"latest","signature_verified":true,"retention_days":30,"size_bytes":1}`,
135			"missing tag":           `{"repository":"team/app","digest":"` + testDigestA + `","signature_verified":true,"retention_days":30,"size_bytes":1}`,
136			"missing signature":     `{"repository":"team/app","digest":"` + testDigestA + `","tag":"latest","retention_days":30,"size_bytes":1}`,
137			"missing retention":     `{"repository":"team/app","digest":"` + testDigestA + `","tag":"latest","signature_verified":true,"size_bytes":1}`,
138			"missing size":          `{"repository":"team/app","digest":"` + testDigestA + `","tag":"latest","signature_verified":true,"retention_days":30}`,
139			"blank repository":      `{"repository":"   ","digest":"` + testDigestA + `","tag":"latest","signature_verified":true,"retention_days":30,"size_bytes":1}`,
140			"blank tag":             `{"repository":"team/app","digest":"` + testDigestA + `","tag":"  ","signature_verified":true,"retention_days":30,"size_bytes":1}`,
141			"repository wrong type": `{"repository":7,"digest":"` + testDigestA + `","tag":"latest","signature_verified":true,"retention_days":30,"size_bytes":1}`,
142			"digest wrong prefix":   `{"repository":"team/app","digest":"sha512:` + strings.Repeat("a", 64) + `","tag":"latest","signature_verified":true,"retention_days":30,"size_bytes":1}`,
143			"digest uppercase hex":  `{"repository":"team/app","digest":"sha256:` + strings.Repeat("A", 64) + `","tag":"latest","signature_verified":true,"retention_days":30,"size_bytes":1}`,
144			"digest too short":      `{"repository":"team/app","digest":"sha256:` + strings.Repeat("a", 63) + `","tag":"latest","signature_verified":true,"retention_days":30,"size_bytes":1}`,
145			"signature not bool":    `{"repository":"team/app","digest":"` + testDigestA + `","tag":"latest","signature_verified":"true","retention_days":30,"size_bytes":1}`,
146			"retention zero":        `{"repository":"team/app","digest":"` + testDigestA + `","tag":"latest","signature_verified":true,"retention_days":0,"size_bytes":1}`,
147			"retention too large":   `{"repository":"team/app","digest":"` + testDigestA + `","tag":"latest","signature_verified":true,"retention_days":3651,"size_bytes":1}`,
148			"retention fractional":  `{"repository":"team/app","digest":"` + testDigestA + `","tag":"latest","signature_verified":true,"retention_days":1.5,"size_bytes":1}`,
149			"retention as string":   `{"repository":"team/app","digest":"` + testDigestA + `","tag":"latest","signature_verified":true,"retention_days":"30","size_bytes":1}`,
150			"size negative":         `{"repository":"team/app","digest":"` + testDigestA + `","tag":"latest","signature_verified":true,"retention_days":30,"size_bytes":-1}`,
151			"size fractional":       `{"repository":"team/app","digest":"` + testDigestA + `","tag":"latest","signature_verified":true,"retention_days":30,"size_bytes":1.5}`,
152		}
153		for name, body := range cases {
154			t.Run(name, func(t *testing.T) {
155				router, _ := newTestRouter(t)
156				recorder := postArtifact(t, router, body)
157				if recorder.Code != http.StatusBadRequest {
158					t.Fatalf("status = %d, want %d (%s)", recorder.Code, http.StatusBadRequest, recorder.Body)
159				}
160				if code := errorCode(t, recorder); code != codeInvalidInput {
161					t.Fatalf("error code = %q, want %q", code, codeInvalidInput)
162				}
163				// A rejected registration must leave no record behind.
164				lookup := getArtifacts(t, router, "repository=team/app")
165				if lookup.Code != http.StatusNotFound {
166					t.Fatalf("after rejection, list status = %d, want %d", lookup.Code, http.StatusNotFound)
167				}
168			})
