171	
172	func TestRegisterDuplicateReturnsOriginalRecord(t *testing.T) {
173		router, _ := newTestRouter(t)
174	
175		first := postArtifact(t, router, validRegistration(testDigestA))
176		if first.Code != http.StatusCreated {
177			t.Fatalf("first status = %d", first.Code)
178		}
179		firstPushedAt := decodeBody(t, first)["pushed_at"]
180	
181		// Same content after normalization (extra whitespace, unknown field).
182		second := postArtifact(t, router, `{"repository":" team/app ","digest":"`+testDigestA+`","tag":"latest",`+
183			`"signature_verified":true,"retention_days":30,"size_bytes":1024,"unknown":1}`)
184		if second.Code != http.StatusCreated {
